// @latency 1
module byte_fifo #(
    parameter DEPTH = 8
) (
    input wire clk,
    input wire rst,
    input wire [7:0] in_data,
    input wire in_valid,
    output wire in_ready,
    output wire [7:0] out_data,
    output wire out_valid,
    input wire out_ready
);

    function integer clog2;
        input integer value;
        integer i;
        begin
            clog2 = 0;
            for (i = value - 1; i > 0; i = i >> 1)
                clog2 = clog2 + 1;
        end
    endfunction

    localparam integer COUNT_WIDTH = (DEPTH <= 1) ? 1 : $clog2(DEPTH + 1);
    localparam integer PTR_WIDTH = (DEPTH <= 1) ? 1 : clog2(DEPTH);

    reg [7:0] mem [0:DEPTH-1];
    reg [PTR_WIDTH-1:0] read_ptr;
    reg [PTR_WIDTH-1:0] write_ptr;
    reg [COUNT_WIDTH-1:0] occupancy;

    assign in_ready = (occupancy < DEPTH);
    assign out_valid = (occupancy > 0);
    assign out_data = (occupancy > 0) ? mem[read_ptr] : 8'b0;

    always @(posedge clk) begin
        if (rst) begin
            read_ptr <= 0;
            write_ptr <= 0;
            occupancy <= 0;
        end else begin
            if (in_valid && in_ready) begin
                mem[write_ptr] <= in_data;
                if (write_ptr == DEPTH - 1)
                    write_ptr <= 0;
                else
                    write_ptr <= write_ptr + 1'b1;
            end

            if (out_valid && out_ready) begin
                if (read_ptr == DEPTH - 1)
                    read_ptr <= 0;
                else
                    read_ptr <= read_ptr + 1'b1;
            end

            if ((in_valid && in_ready) && !(out_valid && out_ready))
                occupancy <= occupancy + 1'b1;
            else if (!(in_valid && in_ready) && (out_valid && out_ready))
                occupancy <= occupancy - 1'b1;
        end
    end

endmodule

