                            bit_index <= 3'd0;
                            state     <= START;
                        end else begin
                            state <= IDLE;
                        end
                    end else begin
                        clk_count <= clk_count + 1'b1;
                    end
                end

                default: begin
                    state     <= IDLE;
                    clk_count <= {CLK_COUNT_WIDTH{1'b0}};
                    bit_index <= 3'd0;
                    tx_shift  <= 8'd0;
                end
            endcase
        end
    end

endmodule

